VALUES ('#ChangingIreland – Ciara’s Community Diary', 'changingireland-community-diary', '', 'A fabulous account by a rural-dweller caring now for vulnerable relatives. Giving it her best online to continue with important volunteer pursuits. Lived in Dublin for years and has volunteered abroad.', 'https://changingireland.ie/wp-content/uploads/2020/05/bealtaine.jpg', '', '[{"slug":"covid19diaries","title":"Covid-19 Diaries"}]', '[{"slug":"changingireland","title":"#ChangingIreland"},{"slug":"communityaction","title":"#CommunityAction"},{"slug":"communityresponseirl","title":"#CommunityResponseIRL"},{"slug":"covid19","title":"#COVID19"},{"slug":"coronavirus","title":"coronavirus"},{"slug":"covid-19-diary","title":"Covid-19 Diary"}]', '', 248889, 1, '2020-05-07T10:50:08Z', '2020-05-07T10:51:09Z', '2020-05-07T10:50:08Z')
